@startuml

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Driver extends Employee {}

class Planner extends Employee {
  + username : string
  + password : string
}

class AdministrativeStaff extends Employee {
  + username : string
  + password : string
  + fieldOfActivity : string
}

class Customer {
  + name : string
  + billingAddress : string
}

class PartnerCompany {
  + name : string
  + address : string
}

class Vehicle {
  + licensePlateNumber : string
  + mileage : int
}

class RefrigeratedTruck extends Vehicle {}

class SmallVan extends Vehicle {}

class LoadingPlatform extends Vehicle {}

class BoxTruck extends Vehicle {}

class RepairShop {
  + name : string
  + address : string
}

class Repair {
  + duration : string
  + cost : double
}

class Order {
  + packageSize : string
  + comment : string
  + startTime : datetime
  + finishTime : datetime
  + pickUpAddress : string
  + deliveryAddress : string
}

class Assignment {
}

Employee "1" -- "*" Repair : takes vehicle to
Repair "*" -- "1" RepairShop : performed at
Repair "*" -- "1" Vehicle : involves
Repair "*" -- "1" Employee : handled by

Order "*" -- "1" Customer : placed by
Order "*" -- "0..1" PartnerCompany : placed by
Order "*" -- "1" Planner : assigned by
Order "*" -- "1" Vehicle : uses
Order "*" -- "1" Driver : completed by
Order "*" -- "1" Driver : assigned to

Assignment "*" -- "1" Driver : executes
Assignment "*" -- "1" Vehicle : uses
Assignment "*" -- "1" Order : refers to
Assignment "*" -- "1" Planner : manages

@enduml

